  1	import Fastify from 'fastify'
  2	import { lstat, readdir } from 'node:fs/promises'
  3	import { fileURLToPath } from 'node:url'
  4	import { join, resolve } from 'node:path'
  5	import { RequestError, openFixtureRoot, readMarkdownFile, writeMarkdownFile, type FixtureRoot, type ReadFile } from './files.ts'
  6	import { parseMutationBody, performMutation } from './mutations.ts'
  7	
  8	export type Source = 'Pi' | 'Claude'
  9	export type EntryKind = 'directory' | 'file'
 10	export type Entry = { source: Source; path: string; kind: EntryKind }
 11	
 12	const sources: ReadonlyArray<{ name: Source; directory: string }> = [
 13	  { name: 'Pi', directory: 'pi' },
 14	  { name: 'Claude', directory: 'claude' },
 15	]
 16	
 17	/** The repository's fixtures/ folder, resolved from this module rather than the shell's working directory. */
 18	export const defaultFixtureRoot = fileURLToPath(new URL('../fixtures/', import.meta.url))
 19	
 20	/**
 21	 * The fixture root is fixed at startup: MD_MANAGER_FIXTURE_ROOT (containing pi/ and claude/) when set,
 22	 * otherwise the repository fixtures. No request can change it.
 23	 */
 24	export function resolveFixtureRoot(env: NodeJS.ProcessEnv = process.env): string {
 25	  const override = env.MD_MANAGER_FIXTURE_ROOT?.trim()
 26	  return override ? resolve(override) : defaultFixtureRoot
 27	}
 28	
 29	export class SourceError extends Error {
 30	  readonly source: Source
 31	  constructor(source: Source, cause: unknown) {
 32	    super(`Unable to read the ${source} fixture folder. Check that both fixture folders exist and are readable, then refresh.`, { cause })
 33	    this.source = source
 34	  }
 35	}
 36	
 37	// Byte-wise ordering keeps the listing deterministic regardless of locale.
 38	function byName(a: { name: string }, b: { name: string }) {
 39	  return a.name < b.name ? -1 : a.name > b.name ? 1 : 0
 40	}
 41	
 42	/**
 43	 * Lists every directory and regular Markdown file below each source root as one flat, pre-ordered list.
 44	 * Symlinks (including symlinked source roots) are never followed, and a failing source fails the whole listing.
 45	 */
 46	export async function listEntries(root: string): Promise<Entry[]> {
 47	  const entries: Entry[] = []
 48	  async function walk(directory: string, source: Source, prefix: string) {
 49	    const dirents = (await readdir(directory, { withFileTypes: true })).sort(byName)
 50	    for (const dirent of dirents) {
 51	      if (dirent.isSymbolicLink()) continue
 52	      const path = prefix ? `${prefix}/${dirent.name}` : dirent.name
 53	      if (dirent.isDirectory()) {
 54	        entries.push({ source, path, kind: 'directory' })
 55	        await walk(join(directory, dirent.name), source, path)
 56	      } else if (dirent.isFile() && dirent.name.toLowerCase().endsWith('.md')) {
 57	        entries.push({ source, path, kind: 'file' })
 58	      }
 59	    }
 60	  }
 61	  for (const { name, directory } of sources) {
 62	    const sourceRoot = join(root, directory)
 63	    try {
 64	      const stats = await lstat(sourceRoot)
 65	      if (!stats.isDirectory()) throw new Error(`${directory} is not a directory`)
 66	      await walk(sourceRoot, name, '')
 67	    } catch (error) {
 68	      throw new SourceError(name, error)
 69	    }
 70	  }
 71	  return entries
 72	}
 73	
 74	export type AppOptions = {
 75	  /** Injectable for tests that simulate a filesystem read failure deterministically. */
 76	  readFile?: ReadFile
 77	}
 78	
 79	function singleString(value: unknown): string | null {
 80	  return typeof value === 'string' ? value : null
 81	}
 82	
 83	/** Request bodies above this size are rejected with 413 before any file is touched. */
 84	export const REQUEST_BODY_LIMIT = 8 * 1024 * 1024
 85	
 86	const HASH_PATTERN = /^[0-9a-f]{64}$/
 87	
 88	type WriteBody = { source: string; path: string; content: string; expectedHash: string }
 89	
 90	function parseWriteBody(body: unknown): WriteBody {
 91	  if (!body || typeof body !== 'object' || Array.isArray(body)) {
 92	    throw new RequestError(400, 'INVALID_BODY', 'The request body must be a JSON object with source, path, content and expectedHash.')
 93	  }
 94	  const { source, path, content, expectedHash } = body as Record<string, unknown>
 95	  if (typeof source !== 'string') throw new RequestError(400, 'INVALID_SOURCE', 'The source must be Pi or Claude.')
 96	  if (typeof path !== 'string') throw new RequestError(400, 'INVALID_PATH', 'The file path is invalid.')
 97	  if (typeof content !== 'string') throw new RequestError(400, 'INVALID_CONTENT', 'The content must be a string.')
 98	  if (typeof expectedHash !== 'string' || !HASH_PATTERN.test(expectedHash)) {
 99	    throw new RequestError(400, 'INVALID_HASH', 'The expected hash must be the 64-character lowercase SHA-256 from the last read or save.')
100	  }
101	  return { source, path, content, expectedHash }
102	}
103	
104	export function createApp(root: string = resolveFixtureRoot(), options: AppOptions = {}) {
105	  const app = Fastify({ logger: true, bodyLimit: REQUEST_BODY_LIMIT })
106	  let fixtureRoot: FixtureRoot
107	  // Body parsing failures (too large, malformed or non-JSON) must be safe JSON with a stable code.
108	  app.setErrorHandler((error: { statusCode?: number; code?: string }, _request, reply) => {
109	    const status = typeof error.statusCode === 'number' ? error.statusCode : 500
110	    if (status === 413) return reply.code(413).send({ code: 'REQUEST_TOO_LARGE', error: `The request is larger than the ${REQUEST_BODY_LIMIT / (1024 * 1024)} MiB limit. Shorten the document or copy your draft elsewhere.` })
111	    if (status === 415) return reply.code(415).send({ code: 'UNSUPPORTED_MEDIA_TYPE', error: 'The request body must be JSON.' })
112	    if (status >= 400 && status < 500) return reply.code(status).send({ code: 'INVALID_BODY', error: 'The request body could not be read as JSON.' })
113	    app.log.error({ code: error.code }, 'Unhandled request failure')
114	    return reply.code(500).send({ code: 'INTERNAL', error: 'The request failed unexpectedly.' })
115	  })
116	  app.addHook('onReady', async () => { fixtureRoot = await openFixtureRoot(root) })
117	  app.addHook('onClose', async () => { await fixtureRoot?.handle.close() })
118	  app.get('/api/entries', async (_request, reply) => {
119	    try {
120	      return { entries: await listEntries(root) }
121	    } catch (error) {
122	      app.log.error(error, 'Fixture discovery failed')
123	      const message = error instanceof SourceError
124	        ? error.message
125	        : 'Unable to list the fixture folders. Check that both fixture folders exist and are readable, then refresh.'
126	      return reply.code(500).send({ error: message })
127	    }
128	  })
129	  app.get('/api/file', async (request, reply) => {
130	    const query = request.query as Record<string, unknown>
131	    const source = singleString(query.source)
132	    const path = singleString(query.path)
133	    if (source === null || path === null) {
134	      return reply.code(400).send({ error: 'Both the source and path query parameters are required exactly once.' })
135	    }
136	    try {
137	      const document = await readMarkdownFile(fixtureRoot, source, path, options.readFile)
138	      return reply.header('Cache-Control', 'no-store').send(document)
139	    } catch (error) {
140	      if (error instanceof RequestError) return reply.code(error.status).send({ code: error.code, error: error.message })
141	      app.log.error(error, 'File read failed')
142	      return reply.code(500).send({ code: 'READ_FAILED', error: 'The file could not be read. Check that it is readable, then retry.' })
143	    }
144	  })
145	  app.put('/api/file', async (request, reply) => {
146	    try {
147	      const body = parseWriteBody(request.body)
148	      const result = await writeMarkdownFile(fixtureRoot, body.source, body.path, body.content, body.expectedHash)
149	      return reply.header('Cache-Control', 'no-store').send(result)
150	    } catch (error) {
151	      if (error instanceof RequestError) return reply.code(error.status).send({ code: error.code, error: error.message })
152	      // Log only the error code: messages can carry absolute paths.
153	      app.log.error({ code: (error as NodeJS.ErrnoException)?.code }, 'File write failed')
154	      return reply.code(500).send({ code: 'WRITE_FAILED', error: 'The file could not be written. Your draft is unchanged; retry or copy it.' })
155	    }
156	  })
157	  app.post('/api/mutate', async (request, reply) => {
158	    try {
159	      const mutation = parseMutationBody(request.body)
160	      const result = await performMutation(fixtureRoot, mutation)
161	      return reply.code(result.status).header('Cache-Control', 'no-store').send(result.body)
162	    } catch (error) {
163	      if (error instanceof RequestError) return reply.code(error.status).send({ code: error.code, error: error.message })
164	      const code = (error as NodeJS.ErrnoException)?.code
165	      if (code === 'ENOENT' || code === 'ENOTDIR' || code === 'ELOOP') {
166	        return reply.code(404).send({ code: 'NOT_FOUND', error: 'The target or its folder was not found.' })
167	      }
168	      app.log.error({ code }, 'Mutation failed')
169	      return reply.code(500).send({ code: 'MUTATION_FAILED', error: 'The operation failed unexpectedly. Refresh the listing to see the current state.' })
170	    }
171	  })
172	  return app
173	}
