  2	import fs, { type FileHandle } from 'node:fs/promises'
  3	import { constants } from 'node:fs'
  4	import { isAbsolute, relative, resolve, sep } from 'node:path'
  5	
  6	export type Source = 'Pi' | 'Claude'
  7	
  8	/** The only directories a request can ever address. A request source is mapped, never used as a directory name. */
  9	const SOURCE_DIRECTORIES: Readonly<Record<Source, string>> = { Pi: 'pi', Claude: 'claude' }
 10	
 11	export function isSource(value: unknown): value is Source {
 12	  return value === 'Pi' || value === 'Claude'
 13	}
 14	
 15	export function isMarkdownName(name: string): boolean {
 16	  return name.toLowerCase().endsWith('.md')
 17	}
 18	
 19	export function sha256(bytes: Buffer): string {
 20	  return createHash('sha256').update(bytes).digest('hex')
 21	}
 22	
 23	/** A rejected request: `status` is the HTTP status, `code` is stable and machine-readable, `message` is safe to send. */
 24	export class RequestError extends Error {
 25	  readonly status: number
 26	  readonly code: string
 27	  constructor(status: number, code: string, message: string) {
 28	    super(message)
 29	    this.status = status
 30	    this.code = code
 31	  }
 32	}
 33	
 34	export class PathError extends RequestError {
 35	  constructor(status: 400 | 404, message: string, code = status === 400 ? 'INVALID_PATH' : 'NOT_FOUND') {
 36	    super(status, code, message)
 37	  }
 38	}
 39	
 40	const INVALID_PATH = 'The file path is invalid.'
 41	export const NOT_FOUND = 'The file was not found or is not a Markdown file.'
 42	export const HASH_CONFLICT_MESSAGE = 'This file changed on disk. Reload it or copy your draft.'
 43	
 44	/**
 45	 * Splits a relative path into safe components. Rejects before any normalisation: `..` and `.` components,
 46	 * empty components (leading, trailing or doubled separators), backslashes, NULs and absolute forms,
 47	 * including Windows drive letters and UNC prefixes.
 48	 */
 49	export function splitRelativePath(path: string): string[] {
 50	  if (typeof path !== 'string' || path.length === 0) throw new PathError(400, INVALID_PATH)
 51	  if (path.includes('\0') || path.includes('\\')) throw new PathError(400, INVALID_PATH)
 52	  if (path.startsWith('/') || isAbsolute(path) || /^[A-Za-z]:/.test(path)) throw new PathError(400, INVALID_PATH)
 53	  const components = path.split('/')
 54	  for (const component of components) {
 55	    if (component === '' || component === '.' || component === '..') throw new PathError(400, INVALID_PATH)
 56	  }
 57	  return components
 58	}
 59	
 60	/** Runs mutations one at a time so two app requests can never interleave their check-then-write steps. */
 61	export class MutationQueue {
 62	  private tail: Promise<unknown> = Promise.resolve()
 63	  run<T>(task: () => Promise<T>): Promise<T> {
 64	    const result = this.tail.then(task, task)
 65	    this.tail = result.catch(() => undefined)
 66	    return result
 67	  }
 68	}
 69	
 70	export type FixtureRoot = { directory: string; handle: FileHandle; mutations: MutationQueue }
 71	export type ReadFile = (file: FileHandle) => Promise<Buffer>
 72	export type FileDocument = { source: Source; path: string; content: string; hash: string }
 73	
 74	const DIRECTORY_FLAGS = constants.O_RDONLY | constants.O_DIRECTORY | constants.O_NOFOLLOW
 75	const FILE_FLAGS = constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK
 76	export const CREATE_FLAGS = constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL | constants.O_NOFOLLOW
 77	const CAPABILITY_ERROR = 'Secure file reads require Linux with mounted procfs at /proc/self/fd.'
 78	
 79	/** No pathname fallback: Node lacks openat, so descriptor-relative traversal requires Linux procfs. */
 80	export async function openFixtureRoot(directory: string): Promise<FixtureRoot> {
 81	  if (process.platform !== 'linux' || !constants.O_NOFOLLOW || !constants.O_DIRECTORY) {
 82	    throw new Error(CAPABILITY_ERROR)
 83	  }
 84	  try {
 85	    const stats = await fs.statfs('/proc/self/fd')
 86	    if (stats.type !== 0x9fa0) throw new Error('Not procfs')
 87	  } catch (cause) { throw new Error(CAPABILITY_ERROR, { cause }) }
 88	  // The configured root and its ancestors are trusted startup configuration, not request input.
 89	  // Pin it once; every source/descendant is subsequently opened relative to a retained descriptor.
 90	  const handle = await fs.open(resolve(directory), DIRECTORY_FLAGS)
 91	  try {
 92	    const probe = await fs.open(`/proc/self/fd/${handle.fd}`, constants.O_RDONLY | constants.O_DIRECTORY)
 93	    await probe.close()
 94	  } catch (cause) {
 95	    await handle.close()
 96	    throw new Error(CAPABILITY_ERROR, { cause })
 97	  }
 98	  return { directory: resolve(directory), handle, mutations: new MutationQueue() }
 99	}
100	
101	function filesystemError(error: unknown): never {
102	  const code = (error as NodeJS.ErrnoException)?.code
103	  if (code === 'ENOENT' || code === 'ENOTDIR' || code === 'ELOOP') {
104	    throw new PathError(404, NOT_FOUND)
105	  }
106	  throw error
107	}
108	
109	/** A descriptor-relative path: the parent is an already-open directory, the name is one validated component. */
110	export function at(parent: FileHandle, name: string): string {
111	  return `/proc/self/fd/${parent.fd}/${name}`
112	}
113	
114	export type Target = { source: Source; components: string[] }
115	
116	/** Validates source and path lexically and returns the safe components. Nothing on disk is touched. */
117	export function validateEntryPath(source: unknown, path: unknown, kind: 'file' | 'folder' | 'any'): Target {
118	  if (!isSource(source)) throw new PathError(400, 'The source must be Pi or Claude.', 'INVALID_SOURCE')
119	  if (typeof path !== 'string') throw new PathError(400, INVALID_PATH)
120	  const components = splitRelativePath(path)
121	  const sourceRoot = resolve('/', SOURCE_DIRECTORIES[source])
122	  const inside = relative(sourceRoot, resolve(sourceRoot, ...components))
123	  if (!inside || inside === '..' || inside.startsWith(`..${sep}`) || isAbsolute(inside)) {
124	    throw new PathError(400, INVALID_PATH)
125	  }
126	  const markdown = isMarkdownName(components[components.length - 1])
127	  if (kind === 'file' && !markdown) throw new PathError(400, 'The file name must end in .md.')
128	  if (kind === 'folder' && markdown) throw new PathError(400, 'A folder name must not end in .md.')
129	  return { source, components }
130	}
131	
132	/** Read/write validation: a non-Markdown name is reported as an unavailable file, not a malformed path. */
133	export function validateMarkdownPath(source: unknown, path: unknown): Target {
134	  const target = validateEntryPath(source, path, 'any')
135	  if (!isMarkdownName(target.components[target.components.length - 1])) throw new PathError(404, NOT_FOUND)
136	  return target
137	}
138	
139	/**
140	 * Walks from the pinned root to the directory containing the target, one no-follow open per component.
141	 * O_NOFOLLOW applies to ONE component at each step; the parent is an already-open directory.
142	 * Rename/symlink replacement can therefore only yield the pinned original or an unavailable target,
143	 * never re-resolve an earlier component. Keep all handles alive until the operation completes.
144	 */
145	export async function withParentDirectory<T>(
146	  root: FixtureRoot, source: Source, components: string[],
147	  operation: (parent: FileHandle, name: string, track: (handle: FileHandle) => void) => Promise<T>,
148	): Promise<T> {
149	  const handles: FileHandle[] = []
150	  try {
151	    let parent = root.handle
152	    for (const component of [SOURCE_DIRECTORIES[source], ...components.slice(0, -1)]) {
153	      parent = await fs.open(at(parent, component), DIRECTORY_FLAGS)
154	      handles.push(parent)
155	    }
156	    return await operation(parent, components[components.length - 1], handle => handles.push(handle))
157	  } catch (error) { filesystemError(error) }
158	  finally { await Promise.all(handles.reverse().map(handle => handle.close())) }
159	}
160	
161	/** Opens the final component no-follow and non-blocking and requires a regular file. */
162	export async function openRegularFile(parent: FileHandle, name: string): Promise<FileHandle> {
163	  // ENXIO here identifies an unopenable special target (e.g. a socket), not a read failure.
164	  // O_NONBLOCK lets us fstat/reject FIFOs without waiting for a writer.
165	  const file = await fs.open(at(parent, name), FILE_FLAGS).catch(error => {
166	    if ((error as NodeJS.ErrnoException).code === 'ENXIO') throw new PathError(404, NOT_FOUND)
167	    throw error
168	  })
169	  try {
170	    if (!(await file.stat()).isFile()) throw new PathError(404, NOT_FOUND)
171	  } catch (error) {
172	    await file.close()
173	    throw error
174	  }
175	  return file
176	}
177	
178	/** Reusable path validator with a descriptor-scoped operation, never a checked pathname. */
179	export async function withMarkdownFile<T>(
180	  root: FixtureRoot, source: unknown, path: unknown,
181	  operation: (file: FileHandle, identity: { source: Source; path: string }) => Promise<T>,
182	): Promise<T> {
183	  const validated = validateMarkdownPath(source, path)
184	  return withParentDirectory(root, validated.source, validated.components, async (parent, name, track) => {
185	    const file = await openRegularFile(parent, name)
186	    track(file)
187	    return operation(file, { source: validated.source, path: validated.components.join('/') })
188	  })
189	}
190	
191	/** Reads from the validated descriptor once; content and SHA-256 use that same buffer. */
192	export async function readMarkdownFile(
193	  root: FixtureRoot, source: unknown, path: unknown, readFile: ReadFile = file => file.readFile(),
194	): Promise<FileDocument> {
195	  return withMarkdownFile(root, source, path, async (file, identity) => {
196	    const bytes = await readFile(file)
197	    return { ...identity, content: bytes.toString('utf8'), hash: sha256(bytes) }
198	  })
199	}
200	
201	export type WriteResult = { source: Source; path: string; hash: string }
202	
203	/**
204	 * Hash-guarded atomic replacement, serialized with every other app mutation:
205	 * open the pinned original, compare its bytes to the expected hash, stage the new bytes in an exclusively
206	 * created sibling temp file carrying the original mode, re-verify the original's identity and bytes,
207	 * then rename the temp file over it. Any handled failure removes the temp file and leaves the original.
208	 * Residual limit: an external writer racing between the final re-check and the rename is not detected.
209	 */
210	export async function writeMarkdownFile(
211	  root: FixtureRoot, source: unknown, path: unknown, content: string, expectedHash: string,
212	): Promise<WriteResult> {
213	  const validated = validateMarkdownPath(source, path)
214	  return root.mutations.run(() => withParentDirectory(root, validated.source, validated.components, async (parent, name, track) => {
215	    const original = await openRegularFile(parent, name)
216	    track(original)
217	    const stats = await original.stat()
218	    if (sha256(await original.readFile()) !== expectedHash) throw new RequestError(409, 'HASH_CONFLICT', HASH_CONFLICT_MESSAGE)
219	
220	    const bytes = Buffer.from(content, 'utf8')
221	    const tempName = `.${name}.${randomBytes(8).toString('hex')}.tmp`
222	    const temp = await fs.open(at(parent, tempName), CREATE_FLAGS, 0o600)
223	    try {
224	      await temp.chmod(stats.mode & 0o7777)
225	      await temp.writeFile(bytes)
226	      await temp.sync()
227	      await temp.close()
228	      // Staging took time: the same name must still be the same regular file with the expected bytes.
229	      const fresh = await openRegularFile(parent, name).catch(error => {
230	        if (error instanceof PathError) throw new RequestError(409, 'HASH_CONFLICT', HASH_CONFLICT_MESSAGE)
231	        throw error
232	      })
233	      track(fresh)
234	      const freshStats = await fresh.stat()
235	      const unchanged = freshStats.ino === stats.ino && freshStats.dev === stats.dev && sha256(await fresh.readFile()) === expectedHash
236	      if (!unchanged) throw new RequestError(409, 'HASH_CONFLICT', HASH_CONFLICT_MESSAGE)
237	      await fs.rename(at(parent, tempName), at(parent, name))
238	    } catch (error) {
239	      await temp.close().catch(() => undefined)
240	      await fs.unlink(at(parent, tempName)).catch(() => undefined)
241	      throw error
242	    }
243	    return { source: validated.source, path: validated.components.join('/'), hash: sha256(bytes) }
244	  }))
245	}
