  2	import type { Stats } from 'node:fs'
  3	import {
  4	  CREATE_FLAGS, NOT_FOUND, PathError, RequestError, at, isMarkdownName, isSource, openRegularFile, validateEntryPath,
  5	  withParentDirectory, type FixtureRoot, type Source, type Target,
