  8	/**
  9	 * Bounded file and folder operations. Every step is descriptor-relative (see files.ts); nothing here
 10	 * re-resolves a validated pathname. All operations run through the same serial queue as content saves.
 11	 *
 12	 * Collision policy: a filesystem probe (lstat of the destination name inside its open parent) refuses
 13	 * anything that exists, including dangling symlinks; creation uses O_EXCL/mkdir, file renames use
 14	 * link + unlink (link fails on an existing name), folder renames use rename after the probe.
 15	 */
 16	export type MutationRequest =
 17	  | { op: 'create-file'; source: Source; path: string; content: string }
 18	  | { op: 'create-folder'; source: Source; path: string }
 19	  | { op: 'rename'; source: Source; path: string; destinationPath: string }
 20	  | { op: 'move'; source: Source; path: string; destinationPath: string }
 21	  | { op: 'delete'; source: Source; path: string }
 22	  | { op: 'copy'; source: Source; path: string; destinationSource: Source; destinationPath: string }
 23	
 24	export type MutationResult = { status: 200 | 201; body: { op: string; source: Source; path: string; destinationSource?: Source; destinationPath?: string } }
 25	
 26	const DESTINATION_EXISTS = new RequestError(409, 'DESTINATION_EXISTS', 'Something already exists at that destination. Choose another name.')
 27	const FOLDER_NOT_EMPTY = new RequestError(409, 'FOLDER_NOT_EMPTY', 'The folder is not empty. Only empty folders can be renamed, moved or deleted.')
 28	const NO_CHANGE = new RequestError(409, 'NO_CHANGE', 'The destination is the same as the current path.')
 29	
 30	function field(body: Record<string, unknown>, name: string): string {
 31	  const value = body[name]
 32	  if (typeof value !== 'string') throw new RequestError(400, 'INVALID_BODY', `The ${name} field must be a string.`)
 33	  return value
 34	}
 35	
 36	/** Parses the discriminated request body. Source names are checked here; paths are validated by the operation. */
 37	export function parseMutationBody(body: unknown): MutationRequest {
 38	  if (!body || typeof body !== 'object' || Array.isArray(body)) {
 39	    throw new RequestError(400, 'INVALID_BODY', 'The request body must be a JSON object with an op, source and path.')
 40	  }
 41	  const record = body as Record<string, unknown>
 42	  const source = record.source
 43	  if (!isSource(source)) throw new RequestError(400, 'INVALID_SOURCE', 'The source must be Pi or Claude.')
 44	  const path = field(record, 'path')
 45	  switch (record.op) {
 46	    case 'create-file': {
 47	      const content = record.content === undefined ? '' : record.content
 48	      if (typeof content !== 'string') throw new RequestError(400, 'INVALID_CONTENT', 'The content must be a string.')
 49	      return { op: 'create-file', source, path, content }
 50	    }
 51	    case 'create-folder':
