      assert.equal(extension.statusCode, 400)
      assert.deepEqual(await tree(join(root, 'claude')), ['imported/', 'imported/review.md'])
      assert.deepEqual(await tree(join(root, 'pi')), ['skills/', 'skills/review.md'])
