      assert.equal(await readFile(join(root, 'claude', 'nested', 'NOTE.MD'), 'utf8'), 'claude updated')
      assert.equal(await readFile(join(root, 'pi', 'note.md'), 'utf8'), 'third')
    } finally { await app.close() }
  })
})

